import { Link, useRouterState } from "@tanstack/react-router";
import { useMemo, useState, type ReactNode } from "react";
import {
  Activity, ArrowRight, BadgeCheck, BarChart3, Bell, BriefcaseBusiness, Camera, Check, ChevronDown,
  ChevronLeft, ChevronRight, CircleDollarSign, Download, ExternalLink, Eye, FileText, Globe2, Grid3X3,
  Heart, HelpCircle, Home, ImagePlus, Instagram, LayoutDashboard, Link2, Linkedin, Mail, MapPin, Menu,
  MessageCircle, MoreHorizontal, Palette, Pencil, Play, Plus, Search, Send, Settings, Share2, ShieldCheck,
  Sparkles, Trash2, TrendingUp, Upload, UserRound, Users, WandSparkles, Youtube, X, Zap
} from "lucide-react";
import type { LucideIcon } from "lucide-react";
import { Area, AreaChart, CartesianGrid, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts";
import { toast } from "sonner";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Switch } from "@/components/ui/switch";
import { Progress } from "@/components/ui/progress";
import { Checkbox } from "@/components/ui/checkbox";
import { Dialog, DialogContent, DialogDescription, DialogFooter, DialogHeader, DialogTitle } from "@/components/ui/dialog";
import { Sheet, SheetContent, SheetDescription, SheetHeader, SheetTitle } from "@/components/ui/sheet";
import { DropdownMenu, DropdownMenuContent, DropdownMenuItem, DropdownMenuLabel, DropdownMenuSeparator, DropdownMenuTrigger } from "@/components/ui/dropdown-menu";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Tabs, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { cn } from "@/lib/utils";
import { analytics, creator, inquiries, notifications, opportunities, portfolio, services, socialAccounts, stats, websiteTemplates } from "@/lib/creator-data";

type PageKey = "dashboard" | "profile" | "social" | "portfolio" | "services" | "website" | "media-kit" | "opportunities" | "inquiries" | "analytics" | "settings";

const nav: Array<{ to: string; label: string; icon: LucideIcon; key: PageKey; badge?: string }> = [
  { to:"/", label:"Dashboard", icon:LayoutDashboard, key:"dashboard" }, { to:"/profile", label:"My Profile", icon:UserRound, key:"profile" },
  { to:"/social-media", label:"Social Media", icon:Share2, key:"social" }, { to:"/portfolio", label:"Portfolio", icon:Grid3X3, key:"portfolio" },
  { to:"/services", label:"Services & Pricing", icon:CircleDollarSign, key:"services" }, { to:"/website", label:"My Website", icon:Globe2, key:"website" },
  { to:"/media-kit", label:"Media Kit", icon:FileText, key:"media-kit" }, { to:"/opportunities", label:"Opportunities", icon:Sparkles, key:"opportunities", badge:"12" },
  { to:"/inquiries", label:"Inquiries", icon:Mail, key:"inquiries", badge:"3" }, { to:"/analytics", label:"Analytics", icon:BarChart3, key:"analytics" },
  { to:"/settings", label:"Settings", icon:Settings, key:"settings" },
];
const titles: Record<PageKey,{title:string; subtitle:string}> = {
 dashboard:{title:"Creator dashboard",subtitle:"Your business, content and community at a glance."}, profile:{title:"My profile",subtitle:"Shape how brands and your audience see you."},
 social:{title:"Social media",subtitle:"Your connected channels and audience health."}, portfolio:{title:"Portfolio",subtitle:"Curate the work that tells your story best."},
 services:{title:"Services & pricing",subtitle:"Package your creativity for the right partnerships."}, website:{title:"My website",subtitle:"A beautiful home for your creator business."},
 "media-kit":{title:"Media kit",subtitle:"Everything a brand needs to say yes."}, opportunities:{title:"Opportunities",subtitle:"Campaigns thoughtfully matched to your work."},
 inquiries:{title:"Inquiries",subtitle:"Keep every brand conversation moving."}, analytics:{title:"Analytics",subtitle:"Understand what is earning attention."},
 settings:{title:"Settings",subtitle:"Manage your workspace, visibility and security."},
};

export function CreatorWorkspace({ page }: { page: PageKey }) {
 const [mobileOpen,setMobileOpen]=useState(false); const [searchOpen,setSearchOpen]=useState(false); const [noticeOpen,setNoticeOpen]=useState(false);
 return <div className="min-h-screen bg-background text-foreground">
  <CreatorSidebar />
  <div className="min-w-0 lg:pl-[248px]">
   <CreatorHeader page={page} onMenu={()=>setMobileOpen(true)} onSearch={()=>setSearchOpen(true)} onNotices={()=>setNoticeOpen(true)} />
   <main className="mx-auto max-w-[1440px] px-4 pb-28 pt-5 sm:px-6 lg:px-8 lg:pb-10 lg:pt-7">
    {page==="dashboard"&&<Dashboard/>}{page==="profile"&&<ProfilePage/>}{page==="social"&&<SocialPage/>}{page==="portfolio"&&<PortfolioPage/>}
    {page==="services"&&<ServicesPage/>}{page==="website"&&<WebsitePage/>}{page==="media-kit"&&<MediaKitPage/>}{page==="opportunities"&&<OpportunitiesPage/>}
    {page==="inquiries"&&<InquiriesPage/>}{page==="analytics"&&<AnalyticsPage/>}{page==="settings"&&<SettingsPage/>}
   </main>
  </div>
  <MobileNavigation onMore={()=>setMobileOpen(true)} />
  <NavSheet open={mobileOpen} onOpenChange={setMobileOpen}/><SearchDialog open={searchOpen} onOpenChange={setSearchOpen}/><NotificationsSheet open={noticeOpen} onOpenChange={setNoticeOpen}/>
 </div>;
}

function Brand(){return <Link to="/" className="flex items-center gap-2.5" aria-label="Influencers.com dashboard"><span className="grid size-8 place-items-center rounded-md bg-coral text-primary-foreground"><Sparkles className="size-4"/></span><span className="text-[15px] font-extrabold">Influencers<span className="text-coral">.</span>com</span></Link>}
function CreatorSidebar(){const path=useRouterState({select:s=>s.location.pathname});return <aside className="fixed inset-y-0 left-0 z-40 hidden w-[248px] border-r border-sidebar-border bg-sidebar text-sidebar-foreground lg:flex lg:flex-col"><div className="px-6 py-7"><Brand/></div><nav className="flex-1 space-y-1 overflow-y-auto px-3">{nav.map(n=>{const active=n.to==="/"?path==="/":path.startsWith(n.to);const Icon=n.icon;return <Link key={n.to} to={n.to} className={cn("flex h-10 items-center gap-3 rounded-md px-3 text-[13px] font-semibold transition-colors",active?"bg-sidebar-accent text-sidebar-accent-foreground":"text-sidebar-foreground/70 hover:bg-sidebar-accent/70 hover:text-sidebar-accent-foreground")}><Icon className={cn("size-[18px]",active&&"text-sidebar-primary")}/><span>{n.label}</span>{n.badge&&<span className="ml-auto rounded-full bg-sidebar-primary px-2 py-0.5 text-[10px] text-sidebar-primary-foreground">{n.badge}</span>}</Link>})}</nav><div className="border-t border-sidebar-border p-4"><div className="flex items-center gap-3 rounded-md bg-sidebar-accent/60 p-2.5"><img src={creator.photo} alt="Ananya Nair" className="size-9 rounded-md object-cover"/><div className="min-w-0"><p className="truncate text-xs font-bold text-sidebar-accent-foreground">{creator.name}</p><p className="truncate text-[10px] text-sidebar-foreground/55">Creator Pro</p></div><ChevronRight className="ml-auto size-4 text-sidebar-foreground/50"/></div></div></aside>}
function CreatorHeader({page,onMenu,onSearch,onNotices}:{page:PageKey;onMenu:()=>void;onSearch:()=>void;onNotices:()=>void}){return <header className="sticky top-0 z-30 border-b bg-background/90 backdrop-blur-xl"><div className="grid h-[72px] grid-cols-[auto_minmax(0,1fr)_auto] items-center gap-3 px-4 sm:px-6 lg:px-8"><Button className="lg:hidden" variant="ghost" size="icon" onClick={onMenu} aria-label="Open navigation"><Menu/></Button><div className="min-w-0"><h1 className="truncate text-base font-extrabold sm:text-lg">{titles[page].title}</h1><p className="hidden truncate text-xs text-muted-foreground sm:block">{titles[page].subtitle}</p></div><div className="flex shrink-0 items-center gap-1.5"><Button variant="outline" className="hidden w-48 justify-start text-muted-foreground xl:flex" onClick={onSearch}><Search/> Search <kbd className="ml-auto text-[10px]">⌘K</kbd></Button><Button variant="ghost" size="icon" onClick={onSearch} className="xl:hidden" aria-label="Search"><Search/></Button><Button variant="ghost" size="icon" className="relative" onClick={onNotices} aria-label="Notifications"><Bell/><span className="absolute right-2 top-2 size-2 rounded-full bg-coral ring-2 ring-background"/></Button><ProfileMenu/></div></div></header>}
function ProfileMenu(){return <DropdownMenu><DropdownMenuTrigger asChild><Button variant="ghost" className="h-10 gap-2 px-1.5"><img src={creator.photo} alt="" className="size-8 rounded-md object-cover"/><ChevronDown className="hidden size-3 sm:block"/></Button></DropdownMenuTrigger><DropdownMenuContent align="end" className="w-56"><DropdownMenuLabel><p>{creator.name}</p><p className="font-normal text-muted-foreground">{creator.handle}</p></DropdownMenuLabel><DropdownMenuSeparator/><DropdownMenuItem onSelect={()=>toast.info("Public profile preview opened")}><Eye/>View Public Profile</DropdownMenuItem><DropdownMenuItem onSelect={()=>toast.info("Website preview opened")}><ExternalLink/>View Website</DropdownMenuItem><DropdownMenuItem asChild><Link to="/settings"><Settings/>Account Settings</Link></DropdownMenuItem><DropdownMenuSeparator/><DropdownMenuItem onSelect={()=>toast("Logout is disabled in this prototype")}><ChevronLeft/>Logout</DropdownMenuItem></DropdownMenuContent></DropdownMenu>}
function MobileNavigation({onMore}:{onMore:()=>void}){const path=useRouterState({select:s=>s.location.pathname});const links=nav.slice(0,4);return <nav className="fixed inset-x-0 bottom-0 z-40 grid grid-cols-5 border-t bg-background/95 px-2 pb-[max(.5rem,env(safe-area-inset-bottom))] pt-2 backdrop-blur-xl lg:hidden">{links.map(n=>{const Icon=n.icon;const active=n.to==="/"?path==="/":path.startsWith(n.to);return <Link key={n.to} to={n.to} className={cn("flex min-w-0 flex-col items-center gap-1 py-1 text-[10px] font-semibold",active?"text-coral":"text-muted-foreground")}><Icon className="size-5"/><span className="truncate">{n.label.replace("My ","")}</span></Link>})}<button onClick={onMore} className="flex flex-col items-center gap-1 py-1 text-[10px] font-semibold text-muted-foreground"><MoreHorizontal className="size-5"/>More</button></nav>}
function NavSheet({open,onOpenChange}:{open:boolean;onOpenChange:(v:boolean)=>void}){return <Sheet open={open} onOpenChange={onOpenChange}><SheetContent side="left" className="w-[88vw] max-w-sm p-0"><SheetHeader className="border-b p-5 text-left"><SheetTitle><Brand/></SheetTitle><SheetDescription>Creator workspace</SheetDescription></SheetHeader><nav className="grid grid-cols-2 gap-2 p-4">{nav.map(n=>{const Icon=n.icon;return <Link key={n.to} to={n.to} onClick={()=>onOpenChange(false)} className="flex min-h-20 flex-col justify-between rounded-md border bg-card p-3 text-xs font-bold"><Icon className="size-5 text-coral"/><span>{n.label}</span></Link>})}</nav></SheetContent></Sheet>}
function SearchDialog({open,onOpenChange}:{open:boolean;onOpenChange:(v:boolean)=>void}){const [q,setQ]=useState("");const results=nav.filter(n=>n.label.toLowerCase().includes(q.toLowerCase()));return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent className="top-[15%] translate-y-0 p-0 sm:max-w-xl"><DialogHeader className="sr-only"><DialogTitle>Search workspace</DialogTitle><DialogDescription>Find pages and creator tools.</DialogDescription></DialogHeader><div className="flex items-center gap-3 border-b px-4"><Search className="size-5 text-muted-foreground"/><Input autoFocus value={q} onChange={e=>setQ(e.target.value)} placeholder="Search pages, campaigns, services…" className="h-14 border-0 shadow-none focus-visible:ring-0"/></div><div className="max-h-80 p-2">{results.map(n=>{const Icon=n.icon;return <Link key={n.to} to={n.to} onClick={()=>onOpenChange(false)} className="flex items-center gap-3 rounded-md p-3 text-sm font-semibold hover:bg-muted"><Icon className="size-4 text-coral"/>{n.label}<ArrowRight className="ml-auto size-4 text-muted-foreground"/></Link>})}</div></DialogContent></Dialog>}
function NotificationsSheet({open,onOpenChange}:{open:boolean;onOpenChange:(v:boolean)=>void}){const [read,setRead]=useState<string[]>([]);return <Sheet open={open} onOpenChange={onOpenChange}><SheetContent className="w-full overflow-y-auto sm:max-w-md"><SheetHeader className="text-left"><SheetTitle>Notifications</SheetTitle><SheetDescription>What’s happening across your creator business.</SheetDescription></SheetHeader><div className="mt-6 space-y-2">{notifications.map(n=><button key={n.id} onClick={()=>setRead(r=>[...r,n.id])} className={cn("w-full rounded-md border p-4 text-left transition-colors hover:bg-muted",n.unread&&!read.includes(n.id)&&"border-coral/30 bg-coral-soft/50")}><div className="flex gap-3"><span className="mt-1 size-2 shrink-0 rounded-full bg-coral"/><div><p className="text-sm font-bold">{n.title}</p><p className="mt-1 text-xs leading-5 text-muted-foreground">{n.text}</p><p className="mt-2 text-[10px] font-bold uppercase text-muted-foreground">{n.time}</p></div></div></button>)}</div></SheetContent></Sheet>}

function SectionHead({eyebrow,title,action}:{eyebrow?:string;title:string;action?:ReactNode}){return <div className="mb-4 grid grid-cols-[minmax(0,1fr)_auto] items-end gap-3"><div className="min-w-0">{eyebrow&&<p className="mb-1 text-[10px] font-extrabold uppercase text-coral">{eyebrow}</p>}<h2 className="font-display text-2xl leading-tight sm:text-3xl">{title}</h2></div>{action}</div>}
function Badge({children,tone="neutral"}:{children:ReactNode;tone?:"neutral"|"coral"|"teal"|"dark"}){return <span className={cn("inline-flex items-center gap-1 rounded-full px-2 py-1 text-[10px] font-extrabold",tone==="neutral"&&"bg-muted text-muted-foreground",tone==="coral"&&"bg-coral-soft text-coral",tone==="teal"&&"bg-teal-soft text-teal",tone==="dark"&&"bg-primary text-primary-foreground")}>{children}</span>}
function StatCard({s,index}:{s:typeof stats[number];index:number}){return <div className="creator-card min-w-[220px] flex-1 p-4 sm:min-w-0"><div className="flex items-start justify-between"><p className="text-xs font-bold text-muted-foreground">{s.label}</p><span className={cn("grid size-8 place-items-center rounded-md",index%2?"bg-teal-soft text-teal":"bg-coral-soft text-coral")}>{index===0?<Eye/>:index===1?<Globe2/>:index===2?<Users/>:<Mail/>}</span></div><div className="mt-5 flex items-end justify-between"><div><p className="text-2xl font-extrabold">{s.value}</p><p className="mt-1 text-[10px] font-bold text-teal">{s.change}</p></div><MiniChart values={s.series}/></div></div>}
function MiniChart({values}:{values:number[]}){const max=Math.max(...values);return <div className="flex h-9 items-end gap-1">{values.map((v,i)=><span key={i} className="w-1.5 rounded-t-sm bg-coral/60" style={{height:`${Math.max(18,(v/max)*100)}%`}}/>)}</div>}
function ProfileCompletion(){return <div className="creator-card relative overflow-hidden bg-primary p-5 text-primary-foreground sm:p-6"><div className="absolute inset-y-0 right-0 w-1/3 subtle-grid opacity-20"/><div className="relative grid gap-5 sm:grid-cols-[1fr_auto] sm:items-center"><div><div className="flex items-center gap-2"><Badge tone="coral"><Sparkles className="size-3"/>LEVEL UP</Badge><span className="text-xs text-primary-foreground/60">Profile {creator.completion}% complete</span></div><h2 className="mt-3 max-w-xl font-display text-3xl leading-tight sm:text-4xl">Your next opportunity starts with a complete story.</h2><p className="mt-2 max-w-lg text-sm leading-6 text-primary-foreground/65">Add recent brand results and your preferred collaboration formats.</p></div><div className="min-w-44"><Progress value={creator.completion} className="mb-3 h-2 bg-primary-foreground/15"/><Button asChild className="w-full bg-coral text-primary-foreground hover:bg-coral/90"><Link to="/profile">Complete profile <ArrowRight/></Link></Button></div></div></div>}

function Dashboard(){return <div className="space-y-7"><div className="grid gap-1"><p className="text-xs font-bold text-coral">SUNDAY · SEPTEMBER 27</p><h2 className="font-display text-3xl sm:text-4xl">Good morning, {creator.name.split(" ")[0]}.</h2></div><ProfileCompletion/><div className="-mx-4 flex snap-x gap-3 overflow-x-auto px-4 pb-2 sm:mx-0 sm:grid sm:grid-cols-2 sm:px-0 xl:grid-cols-4">{stats.map((s,i)=><StatCard key={s.label} s={s} index={i}/>)}</div><div className="grid gap-6 xl:grid-cols-[1.4fr_.8fr]"><WebsitePrompt/><ProfilePreview/></div><div className="grid gap-6 xl:grid-cols-[1.2fr_1fr]"><div><SectionHead eyebrow="FRESH MATCHES" title="Made for your audience" action={<Button variant="ghost" asChild><Link to="/opportunities">View all <ArrowRight/></Link></Button>}/><div className="grid gap-3 sm:grid-cols-2">{opportunities.slice(0,2).map(o=><CampaignCard key={o.id} item={o}/>)}</div></div><div><SectionHead eyebrow="LATEST" title="Recent inquiries" action={<Button variant="ghost" asChild><Link to="/inquiries">Inbox <ArrowRight/></Link></Button>}/><div className="creator-card divide-y">{inquiries.slice(0,3).map(i=><div key={i.id} className="flex gap-3 p-4"><span className="grid size-9 shrink-0 place-items-center rounded-md bg-teal-soft text-xs font-black text-teal">{i.business.slice(0,2).toUpperCase()}</span><div className="min-w-0"><p className="truncate text-xs font-bold">{i.business}</p><p className="truncate text-xs text-muted-foreground">{i.campaign}</p></div><span className="ml-auto text-[10px] text-muted-foreground">{i.date.split(",")[0]}</span></div>)}</div></div></div></div>}
function WebsitePrompt(){return <div className="creator-card relative min-h-[300px] overflow-hidden bg-coral-soft p-6 sm:p-8"><div className="absolute right-[-4%] top-[-20%] size-64 rotate-12 rounded-full border-[34px] border-coral/10"/><Badge tone="coral"><Globe2 className="size-3"/>YOUR SPACE, YOUR STORY</Badge><h2 className="mt-5 max-w-lg font-display text-3xl sm:text-4xl">Create your professional influencer website</h2><p className="mt-3 max-w-lg text-sm leading-6 text-muted-foreground">Turn your profile, portfolio, social media, and services into a professional website.</p><Button asChild className="mt-6"><Link to="/website">Create My Website <ArrowRight/></Link></Button></div>}
function ProfilePreview(){return <div className="creator-card overflow-hidden"><div className="relative h-28"><img src={creator.cover} alt="Kerala backwaters" className="h-full w-full object-cover"/><span className="absolute inset-0 bg-primary/20"/></div><div className="relative px-5 pb-5"><img src={creator.photo} alt={creator.name} className="-mt-10 size-20 rounded-md border-4 border-card object-cover"/><div className="mt-3 flex items-start justify-between gap-3"><div><h3 className="flex items-center gap-1 text-lg font-extrabold">{creator.name}<BadgeCheck className="size-4 text-teal"/></h3><p className="text-xs text-muted-foreground">{creator.category}</p></div><Badge tone="teal">VERIFIED</Badge></div><p className="mt-3 flex items-center gap-1 text-xs text-muted-foreground"><MapPin className="size-3"/>{creator.location}</p><div className="mt-5 flex items-center gap-2"><Button className="flex-1" asChild><Link to="/profile">View Profile</Link></Button><Button variant="outline" size="icon" onClick={()=>toast.success("Public link copied")}><Link2/></Button></div></div></div>}

function PageTop({label,children}:{label?:string;children?:ReactNode}){return <div className="mb-6 flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="text-xs font-bold text-coral">{label||"CREATOR WORKSPACE"}</p><h2 className="mt-1 font-display text-3xl sm:text-4xl">{titles[pathKey()].title}</h2></div>{children}</div>}
function pathKey():PageKey {if(typeof window==="undefined")return "dashboard";const p=window.location.pathname;return p==="/"?"dashboard":p.slice(1).replace("social-media","social") as PageKey}
function Labeled({label,children}:{label:string;children:ReactNode}){return <label className="grid gap-2 text-xs font-bold"><span>{label}</span>{children}</label>}

function ProfilePage(){return <div><PageTop label="MAKE A STRONG FIRST IMPRESSION"><Button onClick={()=>toast.success("Profile changes saved")}><Check/>Save Changes</Button></PageTop><div className="grid gap-6 xl:grid-cols-[1fr_360px]"><div className="space-y-6"><FormSection title="Basic information" desc="The essentials shown across your public profile."><div className="flex flex-col gap-5 sm:flex-row"><div className="relative shrink-0"><img src={creator.photo} alt="" className="size-24 rounded-md object-cover"/><Button size="icon" className="absolute -bottom-2 -right-2"><Camera/></Button></div><div className="grid flex-1 gap-4 sm:grid-cols-2"><Labeled label="Full name"><Input defaultValue={creator.name}/></Labeled><Labeled label="Display name"><Input defaultValue={creator.displayName}/></Labeled><Labeled label="Location"><Input defaultValue={creator.location}/></Labeled><Labeled label="Languages"><Input defaultValue={creator.languages.join(", ")}/></Labeled></div></div><Labeled label="Bio"><Textarea defaultValue={creator.bio} rows={3}/></Labeled><Labeled label="Categories"><Input defaultValue="Travel, Food, Lifestyle"/></Labeled><div><p className="mb-2 text-xs font-bold">Cover image</p><div className="relative h-40 overflow-hidden rounded-md"><img src={creator.cover} alt="" className="h-full w-full object-cover"/><Button variant="secondary" className="absolute bottom-3 right-3"><Upload/>Change cover</Button></div></div></FormSection><FormSection title="Professional information" desc="Help brands understand your experience and point of view."><Labeled label="About"><Textarea defaultValue={creator.about} rows={5}/></Labeled><div className="grid gap-4 sm:grid-cols-2"><Labeled label="Creator type"><Input defaultValue={creator.creatorType}/></Labeled><Labeled label="Experience"><Input defaultValue="6 years"/></Labeled></div><Labeled label="Previous collaborations"><Input defaultValue="Kerala Tourism, Maya Weaves, Nila Kitchens, Cliff House"/></Labeled><Labeled label="Achievements"><Textarea defaultValue="Featured in Travel + Leisure India · Kerala Creator Awards 2025 finalist" rows={2}/></Labeled></FormSection></div><div className="xl:sticky xl:top-24 xl:self-start"><SectionHead eyebrow="LIVE PREVIEW" title="Public profile"/><ProfilePreview/></div></div></div>}
function FormSection({title,desc,children}:{title:string;desc:string;children:ReactNode}){return <section className="creator-card p-5 sm:p-6"><h3 className="text-lg font-extrabold">{title}</h3><p className="mt-1 text-xs text-muted-foreground">{desc}</p><div className="mt-6 space-y-5">{children}</div></section>}

function SocialPage(){const [request,setRequest]=useState(false);const [add,setAdd]=useState(false);return <div><PageTop label="YOUR REACH, IN ONE PLACE"><div className="flex gap-2"><Button variant="outline" onClick={()=>setRequest(true)}>Request a Social Platform</Button><Button onClick={()=>setAdd(true)}><Plus/>Add Social Platform</Button></div></PageTop><div className="mb-6 grid gap-3 sm:grid-cols-3"><QuickMetric label="Total following" value="438K" detail="Across 4 channels"/><QuickMetric label="Avg. engagement" value="5.4%" detail="Top 12% in your category"/><QuickMetric label="Audience quality" value="Excellent" detail="91% authentic audience"/></div><div className="grid gap-4 md:grid-cols-2">{socialAccounts.map(a=><SocialAccountCard key={a.id} account={a}/>)}</div><RequestPlatform open={request} onOpenChange={setRequest}/><AddSocial open={add} onOpenChange={setAdd}/></div>}
function QuickMetric({label,value,detail}:{label:string;value:string;detail:string}){return <div className="creator-card p-5"><p className="text-xs font-bold text-muted-foreground">{label}</p><p className="mt-2 text-2xl font-extrabold">{value}</p><p className="mt-1 text-[11px] text-teal">{detail}</p></div>}
function PlatformIcon({name}:{name:string}){return <span className="grid size-11 place-items-center rounded-md bg-primary text-primary-foreground">{name==="Instagram"?<Instagram/>:name==="YouTube"?<Youtube/>:name==="LinkedIn"?<Linkedin/>:<Share2/>}</span>}
function SocialAccountCard({account}:{account:typeof socialAccounts[number]}){return <div className="creator-card p-5"><div className="grid grid-cols-[auto_minmax(0,1fr)_auto] items-start gap-3"><PlatformIcon name={account.platform}/><div className="min-w-0"><div className="flex items-center gap-1"><h3 className="font-extrabold">{account.platform}</h3>{account.verified&&<BadgeCheck className="size-4 text-teal"/>}</div><p className="truncate text-xs text-muted-foreground">{account.username}</p></div><Badge tone="teal"><span className="size-1.5 rounded-full bg-teal"/>CONNECTED</Badge></div><div className="mt-6 grid grid-cols-3 divide-x border-y py-4 text-center"><div><strong className="block text-lg">{account.followers}</strong><span className="text-[10px] text-muted-foreground">Followers</span></div><div><strong className="block text-lg">{account.following}</strong><span className="text-[10px] text-muted-foreground">Following</span></div><div><strong className="block text-lg text-teal">{account.engagement}</strong><span className="text-[10px] text-muted-foreground">Engagement</span></div></div><div className="mt-4 flex items-center justify-between text-[11px] text-muted-foreground"><span>Updated {account.updated}</span><Button variant="ghost" size="sm">Manage <ChevronRight/></Button></div></div>}
function RequestPlatform({open,onOpenChange}:{open:boolean;onOpenChange:(v:boolean)=>void}){return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent><DialogHeader><DialogTitle>Request a social platform</DialogTitle><DialogDescription>Tell us what connection would help your creator business.</DialogDescription></DialogHeader><div className="grid gap-4"><Labeled label="Platform name"><Input placeholder="e.g. ShareChat"/></Labeled><Labeled label="Platform URL"><Input placeholder="https://platform.com"/></Labeled><Labeled label="Your profile URL"><Input placeholder="https://platform.com/yourname"/></Labeled><Labeled label="Reason / notes"><Textarea placeholder="How do you use this platform?"/></Labeled></div><DialogFooter><Button onClick={()=>{onOpenChange(false);toast.success("Request submitted")}}>Submit request</Button></DialogFooter></DialogContent></Dialog>}
function AddSocial({open,onOpenChange}:{open:boolean;onOpenChange:(v:boolean)=>void}){return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent><DialogHeader><DialogTitle>Add social platform</DialogTitle><DialogDescription>Connect another channel to your professional profile.</DialogDescription></DialogHeader><Labeled label="Platform"><Select><SelectTrigger><SelectValue placeholder="Choose a platform"/></SelectTrigger><SelectContent>{["Facebook","TikTok","X","LinkedIn","Snapchat","Twitch","Website","Other"].map(x=><SelectItem key={x} value={x}>{x}</SelectItem>)}</SelectContent></Select></Labeled><Labeled label="Profile URL"><Input placeholder="https://…"/></Labeled><DialogFooter><Button onClick={()=>{onOpenChange(false);toast.success("Social platform added")}}>Connect platform</Button></DialogFooter></DialogContent></Dialog>}

function PortfolioPage(){const [reorder,setReorder]=useState(false);const [selected,setSelected]=useState<typeof portfolio[number]|null>(null);const [add,setAdd]=useState(false);return <div><PageTop label="YOUR BEST WORK, BEAUTIFULLY CURATED"><div className="flex gap-2"><Button variant={reorder?"secondary":"outline"} onClick={()=>{setReorder(!reorder);toast.info(reorder?"New order saved":"Drag handles are now active")}}><Grid3X3/>{reorder?"Save order":"Reorder"}</Button><Button onClick={()=>setAdd(true)}><Plus/>Add Portfolio Item</Button></div></PageTop><div className="mb-5 flex gap-2 overflow-x-auto pb-1">{["All work","Reels","Campaigns","Travel","Food","Fashion"].map((x,i)=><Button key={x} size="sm" variant={i===0?"default":"outline"}>{x}</Button>)}</div><PortfolioGrid onSelect={setSelected} reorder={reorder}/><PortfolioPreview item={selected} onClose={()=>setSelected(null)}/><AddPortfolio open={add} onOpenChange={setAdd}/></div>}
function PortfolioGrid({onSelect,reorder}:{onSelect:(x:typeof portfolio[number])=>void;reorder:boolean}){return <div className="grid grid-cols-2 gap-2 sm:grid-cols-3 sm:gap-4 xl:grid-cols-4">{portfolio.map((p,i)=><button key={p.id} onClick={()=>onSelect(p)} className={cn("group relative overflow-hidden rounded-md bg-muted text-left",i===0&&"sm:col-span-2 sm:row-span-2",reorder&&"cursor-grab ring-2 ring-coral/30")}><img src={p.image} alt={p.title} loading="lazy" className={cn("aspect-square h-full w-full object-cover transition duration-500 group-hover:scale-[1.03]",i===0&&"sm:aspect-auto")}/><span className="absolute inset-0 bg-gradient-to-t from-primary/85 via-transparent to-transparent"/><span className="absolute left-3 top-3"><Badge tone="dark">{p.format}</Badge></span>{reorder&&<span className="absolute right-3 top-3 grid size-8 place-items-center rounded-md bg-card"><Grid3X3 className="size-4"/></span>}<span className="absolute inset-x-0 bottom-0 p-3 text-primary-foreground sm:p-4"><strong className="block text-sm sm:text-base">{p.title}</strong><span className="mt-1 hidden text-xs text-primary-foreground/70 sm:block">{p.brand} · {p.views} views</span></span></button>)}</div>}
function PortfolioPreview({item,onClose}:{item:typeof portfolio[number]|null;onClose:()=>void}){return <Dialog open={!!item} onOpenChange={o=>!o&&onClose()}><DialogContent className="overflow-hidden p-0 sm:max-w-3xl">{item&&<div className="grid md:grid-cols-[1.15fr_.85fr]"><img src={item.image} alt={item.title} className="h-full max-h-[70vh] w-full object-cover"/><div className="p-6"><Badge tone="coral">{item.format}</Badge><h3 className="mt-4 font-display text-3xl">{item.title}</h3><p className="mt-2 text-sm text-muted-foreground">A high-performing {item.category.toLowerCase()} story created with {item.brand}.</p><div className="mt-6 space-y-3 border-y py-4 text-xs"><p className="flex justify-between"><span className="text-muted-foreground">Client</span><strong>{item.brand}</strong></p><p className="flex justify-between"><span className="text-muted-foreground">Published</span><strong>{item.date}</strong></p><p className="flex justify-between"><span className="text-muted-foreground">Views</span><strong>{item.views}</strong></p></div><div className="mt-6 flex gap-2"><Button className="flex-1" onClick={()=>toast.info("Opening editor")}><Pencil/>Edit</Button><Button variant="outline" size="icon" onClick={()=>{onClose();toast.success("Item removed from portfolio")}}><Trash2/></Button></div></div></div>}</DialogContent></Dialog>}
function AddPortfolio({open,onOpenChange}:{open:boolean;onOpenChange:(v:boolean)=>void}){return <Dialog open={open} onOpenChange={onOpenChange}><DialogContent><DialogHeader><DialogTitle>Add portfolio item</DialogTitle><DialogDescription>Add campaign work, a reel, video or image story.</DialogDescription></DialogHeader><button className="grid min-h-32 place-items-center rounded-md border border-dashed bg-muted/50 text-center"><span><ImagePlus className="mx-auto mb-2 text-coral"/><strong className="block text-sm">Upload media</strong><small className="text-muted-foreground">Images or video up to 200MB</small></span></button><div className="grid gap-4 sm:grid-cols-2"><Labeled label="Title"><Input placeholder="Campaign title"/></Labeled><Labeled label="Brand / client"><Input placeholder="Brand name"/></Labeled><Labeled label="Category"><Input placeholder="Travel, Food…"/></Labeled><Labeled label="Date"><Input type="date"/></Labeled></div><Labeled label="Description"><Textarea placeholder="Tell the story behind this work"/></Labeled><DialogFooter><Button onClick={()=>{onOpenChange(false);toast.success("Portfolio item added")}}>Add to portfolio</Button></DialogFooter></DialogContent></Dialog>}

function ServicesPage(){const [add,setAdd]=useState(false);return <div><PageTop label="TURN CREATIVITY INTO CLEAR OFFERS"><Button onClick={()=>setAdd(true)}><Plus/>Add Service</Button></PageTop><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{services.map((s,i)=><ServiceCard key={s.id} service={s} index={i}/>)}</div><Dialog open={add} onOpenChange={setAdd}><DialogContent><DialogHeader><DialogTitle>Add a service</DialogTitle><DialogDescription>Create a clear offer brands can inquire about.</DialogDescription></DialogHeader><Labeled label="Service name"><Input placeholder="e.g. YouTube Short"/></Labeled><Labeled label="Description"><Textarea placeholder="What is included?"/></Labeled><div className="grid gap-4 sm:grid-cols-2"><Labeled label="Starting price"><Input placeholder="₹25,000"/></Labeled><Labeled label="Turnaround"><Input placeholder="7–10 days"/></Labeled></div><Labeled label="Deliverables"><Input placeholder="1 video · 2 revisions"/></Labeled><label className="flex items-center gap-2 text-xs font-bold"><Checkbox/> Contact for Price</label><DialogFooter><Button onClick={()=>{setAdd(false);toast.success("Service added")}}>Add service</Button></DialogFooter></DialogContent></Dialog></div>}
function ServiceCard({service,index}:{service:typeof services[number];index:number}){const [active,setActive]=useState(service.active);return <div className="creator-card flex min-h-64 flex-col p-5"><div className="flex items-start justify-between"><span className={cn("grid size-10 place-items-center rounded-md",index%2?"bg-teal-soft text-teal":"bg-coral-soft text-coral")}>{index%2?<Camera/>:<Play/>}</span><div className="flex items-center gap-2"><span className="text-[10px] font-bold text-muted-foreground">{active?"ACTIVE":"HIDDEN"}</span><Switch checked={active} onCheckedChange={setActive}/></div></div><h3 className="mt-5 text-lg font-extrabold">{service.name}</h3><p className="mt-2 text-xs leading-5 text-muted-foreground">{service.description}</p><div className="mt-4 flex-1 space-y-2 border-t pt-4 text-xs"><p><span className="text-muted-foreground">Includes · </span>{service.deliverables}</p><p><span className="text-muted-foreground">Turnaround · </span>{service.turnaround}</p></div><div className="mt-5 flex items-end justify-between"><div><p className="text-[10px] font-bold uppercase text-muted-foreground">Starting at</p><strong className="text-lg">{service.price}</strong></div><Button variant="outline" size="icon" onClick={()=>toast.info(`Editing ${service.name}`)}><Pencil/></Button></div></div>}

function WebsitePage(){const [started,setStarted]=useState(false);const [existing,setExisting]=useState<"existing"|"create"|null>(null);const [step,setStep]=useState(1);const [template,setTemplate]=useState("Travel");const [published,setPublished]=useState(false);const [sections,setSections]=useState(["About","Social Media","Portfolio","Services","Contact"]);if(published)return <WebsiteLive onEdit={()=>{setPublished(false);setStarted(true);setExisting("create");setStep(4)}}/>;if(!started)return <div><PageTop label="BUILD YOUR HOME ON THE INTERNET"/><div className="creator-card overflow-hidden"><div className="grid lg:grid-cols-[1fr_.9fr]"><div className="p-7 sm:p-10"><Badge tone="coral"><WandSparkles className="size-3"/>NO CODE NEEDED</Badge><h2 className="mt-5 max-w-lg font-display text-4xl sm:text-5xl">Create your professional influencer website</h2><p className="mt-4 max-w-lg text-sm leading-6 text-muted-foreground">Turn your profile, portfolio, social media, and services into a professional website.</p><Button size="lg" className="mt-7" onClick={()=>setStarted(true)}>Create My Website <ArrowRight/></Button></div><div className="min-h-80 bg-teal-soft p-6 sm:p-8"><WebsitePreview compact/></div></div></div></div>;
 if(!existing)return <div><PageTop label="WEBSITE SETUP"/><div className="mx-auto max-w-3xl"><StepDots step={0}/><SectionHead title="Do you already have a website?"/><div className="grid gap-4 sm:grid-cols-2"><ChoiceCard icon={<Link2/>} title="I already have a website" desc="Connect your existing website to your profile." onClick={()=>setExisting("existing")}/><ChoiceCard icon={<Sparkles/>} title="Create with Influencers.com" desc="Build a polished creator website in minutes." onClick={()=>setExisting("create")}/></div></div></div>;
 if(existing==="existing")return <div><PageTop label="CONNECT YOUR WEBSITE"/><div className="mx-auto max-w-xl creator-card p-6"><Button variant="ghost" size="sm" onClick={()=>setExisting(null)}><ChevronLeft/>Back</Button><h2 className="mt-4 font-display text-3xl">Add your existing website</h2><p className="mt-2 text-sm text-muted-foreground">We’ll show this link across your creator profile.</p><div className="mt-6"><Labeled label="Existing website URL"><Input placeholder="https://yourwebsite.com"/></Labeled></div><Button className="mt-5 w-full" onClick={()=>toast.success("Website connected")}>Connect website</Button></div></div>;
 return <div><PageTop label={`WEBSITE BUILDER · STEP ${step} OF 4`}><Button variant="ghost" onClick={()=>step===1?setExisting(null):setStep(step-1)}><ChevronLeft/>Back</Button></PageTop><div className="mx-auto max-w-6xl"><StepDots step={step}/>{step===1&&<TemplateStep value={template} onChange={setTemplate}/>} {step===2&&<StyleStep/>} {step===3&&<SectionsStep selected={sections} setSelected={setSections}/>} {step===4&&<div><SectionHead title="Your website is ready for its debut"/><div className="creator-card bg-muted p-3 sm:p-6"><WebsitePreview/></div></div>}<div className="mt-6 flex justify-end"><Button size="lg" onClick={()=>step<4?setStep(step+1):setPublished(true)}>{step<4?<>Continue <ArrowRight/></>:<>Publish Website <Sparkles/></>}</Button></div></div></div>}
function StepDots({step}:{step:number}){return <div className="mb-8 flex items-center gap-2">{[1,2,3,4].map(n=><span key={n} className={cn("h-1.5 flex-1 rounded-full",n<=step?"bg-coral":"bg-border")}/>)}</div>}
function ChoiceCard({icon,title,desc,onClick}:{icon:ReactNode;title:string;desc:string;onClick:()=>void}){return <button onClick={onClick} className="creator-card group p-6 text-left transition hover:-translate-y-1 hover:border-coral"><span className="grid size-12 place-items-center rounded-md bg-coral-soft text-coral">{icon}</span><h3 className="mt-8 text-lg font-extrabold">{title}</h3><p className="mt-2 text-sm leading-6 text-muted-foreground">{desc}</p><ArrowRight className="mt-6 size-5 transition-transform group-hover:translate-x-1"/></button>}
function TemplateStep({value,onChange}:{value:string;onChange:(v:string)=>void}){return <div><SectionHead title="Choose a template that feels like you"/><div className="grid grid-cols-2 gap-3 md:grid-cols-4">{websiteTemplates.map((t,i)=><button key={t} onClick={()=>onChange(t)} className={cn("overflow-hidden rounded-md border bg-card text-left transition hover:-translate-y-1",value===t&&"border-coral ring-2 ring-coral/20")}><div className={cn("aspect-[4/3] p-3",i%3===0?"bg-coral-soft":i%3===1?"bg-teal-soft":"bg-secondary")}><div className="h-full rounded-sm bg-card p-2 shadow-sm"><span className="block h-1.5 w-1/3 bg-primary"/><span className="mt-3 block h-8 bg-muted"/><span className="mt-2 grid grid-cols-2 gap-1"><i className="h-6 bg-border"/><i className="h-6 bg-border"/></span></div></div><div className="flex items-center justify-between p-3"><strong className="text-xs">{t}</strong>{value===t&&<Check className="size-4 text-coral"/>}</div></button>)}</div></div>}
function StyleStep(){const [font,setFont]=useState("Editorial");return <div><SectionHead title="Set your visual rhythm"/><div className="grid gap-5 md:grid-cols-3"><OptionGroup title="Typography" values={["Editorial","Modern","Minimal"]} value={font} onChange={setFont}/><OptionGroup title="Accent style" values={["Coral","Emerald","Golden"]} value="Coral" onChange={()=>{}}/><OptionGroup title="Layout" values={["Magazine","Gallery","Story"]} value="Magazine" onChange={()=>{}}/></div></div>}
function OptionGroup({title,values,value,onChange}:{title:string;values:string[];value:string;onChange:(v:string)=>void}){return <div className="creator-card p-5"><h3 className="mb-4 text-sm font-extrabold">{title}</h3><div className="space-y-2">{values.map(v=><button key={v} onClick={()=>onChange(v)} className={cn("flex w-full items-center justify-between rounded-md border p-3 text-xs font-bold",value===v&&"border-coral bg-coral-soft")}>{v}{value===v&&<Check className="size-4 text-coral"/>}</button>)}</div></div>}
function SectionsStep({selected,setSelected}:{selected:string[];setSelected:(v:string[])=>void}){const all=["About","Social Media","Portfolio","Services","Collaborations","Testimonials","Contact"];return <div><SectionHead title="Choose what your website includes"/><div className="creator-card grid gap-2 p-5 sm:grid-cols-2">{all.map(s=><label key={s} className="flex cursor-pointer items-center gap-3 rounded-md border p-4 text-sm font-bold"><Checkbox checked={selected.includes(s)} onCheckedChange={()=>setSelected(selected.includes(s)?selected.filter(x=>x!==s):[...selected,s])}/>{s}</label>)}</div></div>}
function WebsitePreview({compact=false}:{compact?:boolean}){return <div className={cn("overflow-hidden rounded-md border bg-card shadow-xl",compact&&"rotate-[-1deg]")}><div className="flex items-center justify-between border-b px-4 py-3"><strong className="font-display">Ananya.</strong><span className="text-[9px] font-bold">WORK · ABOUT · CONTACT</span></div><div className="relative aspect-[16/9] overflow-hidden"><img src={creator.cover} alt="Backwaters website cover" className="h-full w-full object-cover"/><div className="absolute inset-0 bg-primary/30"/><div className="absolute inset-x-0 bottom-0 p-5 text-primary-foreground sm:p-8"><p className="text-[9px] font-bold uppercase">KERALA · TRAVEL · FOOD</p><h3 className={cn("mt-1 font-display",compact?"text-2xl":"text-3xl sm:text-5xl")}>Stories rooted in place.</h3></div></div><div className="grid grid-cols-3 gap-2 p-3">{portfolio.slice(1,4).map(p=><img key={p.id} src={p.image} alt="" className="aspect-square w-full object-cover"/>)}</div></div>}
function WebsiteLive({onEdit}:{onEdit:()=>void}){return <div><PageTop label="PUBLISHED & GROWING"><div className="flex gap-2"><Button variant="outline" onClick={()=>toast.info("Website opened in preview")}><ExternalLink/>View Website</Button><Button onClick={onEdit}><Pencil/>Edit Website</Button></div></PageTop><div className="creator-card border-teal/30 bg-teal-soft/40 p-5"><div className="flex items-center gap-3"><span className="grid size-10 place-items-center rounded-full bg-teal text-primary-foreground"><Check/></span><div><h3 className="font-extrabold">Your website is live</h3><p className="text-xs text-muted-foreground">ananya.influencers.com</p></div><Badge tone="teal">LIVE</Badge></div></div><div className="mt-5 grid gap-3 sm:grid-cols-4"><QuickMetric label="Website visitors" value="8,642" detail="Last 30 days"/><QuickMetric label="Status" value="Live" detail="Everything looks good"/><QuickMetric label="Last updated" value="Today" detail="10:22 AM"/><QuickMetric label="Template" value="Travel" detail="Editorial style"/></div><div className="mt-6 grid gap-6 lg:grid-cols-[1fr_360px]"><div className="creator-card bg-muted p-3 sm:p-5"><WebsitePreview/></div><div className="space-y-4"><FormSection title="Website controls" desc="Manage your public site."><Button variant="outline" className="w-full justify-start" onClick={()=>toast.info("Template library opened")}><Palette/>Change Template</Button><Button variant="outline" className="w-full justify-start" onClick={()=>toast.info("SEO settings opened")}><Search/>SEO Settings</Button><Button variant="outline" className="w-full justify-start" onClick={()=>toast.warning("Website unpublished in this preview")}><X/>Unpublish</Button></FormSection><FormSection title="Domain settings" desc="Using Influencers.com domain"><p className="text-sm font-bold">ananya.influencers.com</p><Button className="w-full" onClick={()=>toast.info("Custom domain setup is a preview only")}><Globe2/>Connect your custom domain</Button></FormSection></div></div></div>}

function MediaKitPage(){return <div><PageTop label="A POLISHED INTRODUCTION FOR BRANDS"><div className="flex flex-wrap gap-2"><Button variant="outline" onClick={()=>toast.info("Media kit preview opened")}><Eye/>Preview Media Kit</Button><Button onClick={()=>toast.success("Media kit generated")}><WandSparkles/>Generate Media Kit</Button></div></PageTop><div className="grid gap-6 xl:grid-cols-[1fr_300px]"><MediaKitPreview/><div className="space-y-4"><FormSection title="Share your media kit" desc="Updated today at 10:22 AM"><Button className="w-full" onClick={()=>toast.success("Private share link copied")}><Share2/>Share Media Kit</Button><Button variant="outline" className="w-full" onClick={()=>toast.success("PDF download prepared")}><Download/>Download PDF</Button></FormSection><FormSection title="Included sections" desc="7 of 7 ready">{["Profile & bio","Social statistics","Audience insights","Portfolio highlights","Services","Collaborations","Contact information"].map(x=><p key={x} className="flex items-center gap-2 text-xs"><Check className="size-4 text-teal"/>{x}</p>)}</FormSection></div></div></div>}
function MediaKitPreview(){return <div className="creator-card overflow-hidden"><div className="grid min-h-[760px] md:grid-cols-[.75fr_1.25fr]"><div className="bg-primary p-7 text-primary-foreground"><p className="text-xs font-bold text-coral">MEDIA KIT · 2026</p><img src={creator.photo} alt={creator.name} className="mt-10 aspect-[4/5] w-full rounded-md object-cover"/><h2 className="mt-6 font-display text-4xl">{creator.name}</h2><p className="mt-2 text-sm text-primary-foreground/60">{creator.category}</p><div className="mt-8 space-y-4 border-t border-primary-foreground/15 pt-6 text-xs"><p>{creator.location}</p><p>{creator.email}</p><p>{creator.profileUrl}</p></div></div><div className="p-6 sm:p-9"><Badge tone="coral">KERALA CREATOR</Badge><h3 className="mt-5 font-display text-3xl">Stories that turn a place into a feeling.</h3><p className="mt-4 text-sm leading-6 text-muted-foreground">{creator.about}</p><div className="mt-8 grid grid-cols-3 gap-2 border-y py-5 text-center"><div><strong className="text-xl">438K</strong><p className="text-[9px] text-muted-foreground">TOTAL REACH</p></div><div><strong className="text-xl">5.4%</strong><p className="text-[9px] text-muted-foreground">ENGAGEMENT</p></div><div><strong className="text-xl">72%</strong><p className="text-[9px] text-muted-foreground">INDIA</p></div></div><h4 className="mt-8 text-xs font-black uppercase">Selected work</h4><div className="mt-3 grid grid-cols-3 gap-2">{portfolio.slice(0,3).map(p=><img key={p.id} src={p.image} alt="" className="aspect-[3/4] w-full rounded-sm object-cover"/>)}</div><h4 className="mt-8 text-xs font-black uppercase">Trusted by</h4><p className="mt-3 font-display text-xl text-muted-foreground">Kerala Voyages · Maya Weaves · Nila Kitchens · Cliff House</p></div></div></div>}

function OpportunitiesPage(){const [apply,setApply]=useState<typeof opportunities[number]|null>(null);return <div><PageTop label="CURATED FOR YOUR VOICE"><Badge tone="coral"><Sparkles className="size-3"/>12 NEW MATCHES</Badge></PageTop><div className="creator-card mb-6 grid gap-3 p-3 sm:grid-cols-2 lg:grid-cols-5">{["Category","Platform","Location","Budget","Deadline"].map((x,i)=><Select key={x}><SelectTrigger><SelectValue placeholder={x}/></SelectTrigger><SelectContent>{(i===0?["Travel","Food","Fashion","Lifestyle"]:i===1?["Instagram","YouTube","TikTok"]:i===2?["Kerala","Kochi","Wayanad","Remote"]:["Any","This month","Next month"]).map(v=><SelectItem key={v} value={v}>{v}</SelectItem>)}</SelectContent></Select>)}</div><div className="grid gap-4 md:grid-cols-2">{opportunities.map(o=><CampaignCard key={o.id} item={o} onApply={()=>setApply(o)}/>)}</div><Dialog open={!!apply} onOpenChange={o=>!o&&setApply(null)}><DialogContent>{apply&&<><DialogHeader><DialogTitle>Apply to {apply.name}</DialogTitle><DialogDescription>{apply.business} · {apply.budget}</DialogDescription></DialogHeader><Labeled label="Your pitch"><Textarea rows={5} defaultValue={`Hi ${apply.business}, I’d love to bring ${apply.name} to life through warm, useful storytelling for my Kerala-focused community.`}/></Labeled><Labeled label="Proposed fee"><Input defaultValue={apply.budget.split("–")[0]}/></Labeled><DialogFooter><Button onClick={()=>{setApply(null);toast.success("Application sent")}}><Send/>Send application</Button></DialogFooter></>}</DialogContent></Dialog></div>}
function CampaignCard({item,onApply}:{item:typeof opportunities[number];onApply?:()=>void}){return <div className="creator-card p-5"><div className="flex items-start justify-between gap-3"><span className="grid size-11 place-items-center rounded-md bg-teal-soft font-display text-xl text-teal">{item.business.charAt(0)}</span><Badge tone="coral">{item.match}% MATCH</Badge></div><p className="mt-5 text-[10px] font-bold uppercase text-coral">{item.category} · {item.location}</p><h3 className="mt-1 text-lg font-extrabold">{item.name}</h3><p className="text-xs text-muted-foreground">{item.business}</p><div className="mt-5 grid grid-cols-2 gap-3 border-y py-4 text-xs"><div><p className="text-[10px] text-muted-foreground">DELIVERABLES</p><strong>{item.deliverables}</strong></div><div><p className="text-[10px] text-muted-foreground">BUDGET</p><strong>{item.budget}</strong></div><div><p className="text-[10px] text-muted-foreground">PLATFORM</p><strong>{item.platform}</strong></div><div><p className="text-[10px] text-muted-foreground">DEADLINE</p><strong>{item.deadline}</strong></div></div><div className="mt-4 flex gap-2"><Button variant="outline" className="flex-1" onClick={()=>toast.info(`${item.name} details opened`)}>View Opportunity</Button><Button className="flex-1" onClick={onApply||(()=>toast.success("Application started"))}>Apply</Button></div></div>}

function InquiriesPage(){const [tab,setTab]=useState("New");const [active,setActive]=useState<(typeof inquiries)[number]>(()=>inquiries[0] ?? {id:"empty",business:"No inquiries",campaign:"",message:"",budget:"",date:"",status:"New"});const visible=inquiries.filter(i=>tab==="All"||i.status===tab);return <div><PageTop label="COLLABORATIONS, ORGANIZED"><Button><Pencil/>New message</Button></PageTop><Tabs value={tab} onValueChange={setTab} className="mb-5 overflow-x-auto"><TabsList>{["All","New","Responded","Negotiating","Accepted","Declined"].map(x=><TabsTrigger key={x} value={x}>{x}</TabsTrigger>)}</TabsList></Tabs><div className="creator-card grid min-h-[620px] overflow-hidden lg:grid-cols-[360px_1fr]"><div className="border-b lg:border-b-0 lg:border-r"><div className="border-b p-3"><div className="relative"><Search className="absolute left-3 top-2.5 size-4 text-muted-foreground"/><Input className="pl-9" placeholder="Search inquiries"/></div></div><div className="max-h-72 divide-y overflow-y-auto lg:max-h-[560px]">{visible.map(i=><button key={i.id} onClick={()=>setActive(i)} className={cn("w-full p-4 text-left",active.id===i.id&&"bg-coral-soft")}><div className="flex items-center justify-between"><strong className="text-sm">{i.business}</strong><span className="text-[9px] text-muted-foreground">{i.date}</span></div><p className="mt-1 text-xs font-semibold">{i.campaign}</p><p className="mt-1 truncate text-xs text-muted-foreground">{i.message}</p></button>)}</div></div><Conversation inquiry={active}/></div></div>}
function Conversation({inquiry}:{inquiry:typeof inquiries[number]}){const [reply,setReply]=useState("");return <div className="flex min-h-[520px] flex-col"><div className="grid grid-cols-[minmax(0,1fr)_auto] items-center border-b p-4"><div className="min-w-0"><h3 className="truncate font-extrabold">{inquiry.business}</h3><p className="truncate text-xs text-muted-foreground">{inquiry.campaign} · {inquiry.budget}</p></div><Badge tone={inquiry.status==="Accepted"?"teal":"coral"}>{inquiry.status}</Badge></div><div className="flex-1 space-y-4 bg-muted/40 p-5 sm:p-8"><div className="max-w-lg rounded-md border bg-card p-4"><p className="text-sm leading-6">{inquiry.message}</p><p className="mt-3 text-[10px] text-muted-foreground">{inquiry.date}</p></div><div className="ml-auto max-w-lg rounded-md bg-primary p-4 text-primary-foreground"><p className="text-sm leading-6">Thank you for thinking of me. This sounds aligned with my audience — I’d love to review the full brief and dates.</p><p className="mt-3 text-[10px] text-primary-foreground/60">Draft preview</p></div></div><div className="border-t p-4"><Textarea value={reply} onChange={e=>setReply(e.target.value)} placeholder="Write a thoughtful reply…" rows={3}/><div className="mt-3 flex flex-wrap justify-between gap-2"><div className="flex gap-2"><Button variant="outline" onClick={()=>toast.success("Inquiry accepted")}><Check/>Accept</Button><Button variant="ghost" onClick={()=>toast.warning("Inquiry declined")}>Decline</Button></div><Button onClick={()=>{setReply("");toast.success("Reply sent")}}><Send/>Reply</Button></div></div></div>}

function AnalyticsPage(){const [period,setPeriod]=useState("30 days");return <div><PageTop label="YOUR GROWTH, MADE CLEAR"><div className="flex gap-1 rounded-md border bg-card p-1">{["7 days","30 days","3 months","1 year"].map(x=><Button key={x} size="sm" variant={period===x?"default":"ghost"} onClick={()=>setPeriod(x)}>{x}</Button>)}</div></PageTop><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{[["Profile views","24,812","+18.2%"],["Website visitors","8,642","+12.4%"],["Portfolio views","62,410","+24.6%"],["Social clicks","5,384","+9.1%"],["Contact clicks","1,206","+16.8%"],["Collaboration inquiries","36","+8 this month"]].map(x=><div key={x[0]} className="creator-card p-4"><p className="text-xs font-bold text-muted-foreground">{x[0]}</p><div className="mt-3 flex items-end justify-between"><strong className="text-2xl">{x[1]}</strong><Badge tone="teal"><TrendingUp className="size-3"/>{x[2]}</Badge></div></div>)}</div><div className="creator-card mt-6 p-5 sm:p-6"><SectionHead eyebrow="PERFORMANCE" title="Attention over time"/><div className="h-[320px]"><ResponsiveContainer width="100%" height="100%"><AreaChart data={analytics}><defs><linearGradient id="areaFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stopColor="var(--coral)" stopOpacity={.35}/><stop offset="100%" stopColor="var(--coral)" stopOpacity={0}/></linearGradient></defs><CartesianGrid strokeDasharray="3 3" vertical={false} stroke="var(--border)"/><XAxis dataKey="day" tickLine={false} axisLine={false} fontSize={10}/><YAxis tickLine={false} axisLine={false} fontSize={10}/><Tooltip contentStyle={{borderRadius:8,borderColor:"var(--border)"}}/><Area type="monotone" dataKey="views" stroke="var(--coral)" strokeWidth={3} fill="url(#areaFill)"/><Area type="monotone" dataKey="visitors" stroke="var(--teal)" strokeWidth={2} fill="transparent"/></AreaChart></ResponsiveContainer></div></div><div className="mt-6 grid gap-6 lg:grid-cols-3"><Ranking title="Top Portfolio Content" rows={portfolio.slice(0,3).map(p=>[p.title,p.views])}/><Ranking title="Top Traffic Sources" rows={[["Instagram","46%"],["Google Search","24%"],["Direct","18%"]]}/><Ranking title="Most Viewed Services" rows={[["Instagram Reel","2,840"],["Travel Story Package","1,906"],["UGC Content","1,420"]]}/></div></div>}
function Ranking({title,rows}:{title:string;rows:string[][]}){return <div className="creator-card p-5"><h3 className="font-display text-xl">{title}</h3><div className="mt-5 space-y-4">{rows.map((r,i)=><div key={r[0]} className="grid grid-cols-[auto_minmax(0,1fr)_auto] items-center gap-3"><span className="grid size-7 place-items-center rounded-md bg-muted text-xs font-black">{i+1}</span><span className="truncate text-xs font-bold">{r[0]}</span><strong className="text-xs text-teal">{r[1]}</strong></div>)}</div></div>}

function SettingsPage(){const [danger,setDanger]=useState(false);return <div><PageTop label="MAKE THE WORKSPACE YOURS"/><div className="grid gap-6 lg:grid-cols-[220px_1fr]"><aside className="creator-card h-fit p-2">{["Account","Profile visibility","Notifications","Privacy","Connected accounts","Subscription","Website","Domain","Security"].map((x,i)=><button key={x} className={cn("w-full rounded-md px-3 py-2.5 text-left text-xs font-bold",i===0?"bg-primary text-primary-foreground":"hover:bg-muted")}>{x}</button>)}</aside><div className="space-y-6"><FormSection title="Account" desc="Your creator account details."><div className="grid gap-4 sm:grid-cols-2"><Labeled label="Name"><Input defaultValue={creator.name}/></Labeled><Labeled label="Email"><Input defaultValue={creator.email}/></Labeled></div><Button onClick={()=>toast.success("Account settings saved")}>Save account</Button></FormSection><FormSection title="Profile visibility" desc="Control what potential collaborators can discover."><SettingToggle title="Public creator profile" desc="Show your profile in marketplace search." checked/><SettingToggle title="Show audience insights" desc="Share summary demographics with verified brands." checked/><SettingToggle title="Show starting prices" desc="Display pricing on your public profile."/></FormSection><FormSection title="Notification preferences" desc="Choose what deserves your attention."><SettingToggle title="New collaboration inquiries" desc="Email and push notification." checked/><SettingToggle title="Campaign invitations" desc="Opportunities matched above 80%." checked/><SettingToggle title="Weekly performance digest" desc="A concise Monday analytics email." checked/></FormSection><FormSection title="Security" desc="Keep your workspace protected."><div className="flex items-center justify-between gap-4"><div><p className="text-sm font-bold">Two-step verification</p><p className="text-xs text-muted-foreground">Add an extra layer of account security.</p></div><Button variant="outline" onClick={()=>toast.success("Security setup started")}><ShieldCheck/>Set up</Button></div></FormSection><section className="creator-card border-destructive/30 p-6"><h3 className="font-extrabold text-destructive">Danger zone</h3><p className="mt-1 text-xs text-muted-foreground">Permanently delete your creator workspace and content.</p><Button variant="destructive" className="mt-5" onClick={()=>setDanger(true)}><Trash2/>Delete account</Button></section></div></div><Dialog open={danger} onOpenChange={setDanger}><DialogContent><DialogHeader><DialogTitle>Delete your creator account?</DialogTitle><DialogDescription>This would permanently remove your profile, portfolio, website and inquiries. This prototype will not delete anything.</DialogDescription></DialogHeader><DialogFooter><Button variant="outline" onClick={()=>setDanger(false)}>Cancel</Button><Button variant="destructive" onClick={()=>{setDanger(false);toast.error("Account deletion is disabled in this prototype")}}>Delete permanently</Button></DialogFooter></DialogContent></Dialog></div>}
function SettingToggle({title,desc,checked=false}:{title:string;desc:string;checked?:boolean}){const [on,setOn]=useState(checked);return <div className="flex items-center justify-between gap-4 border-b pb-4 last:border-0 last:pb-0"><div><p className="text-sm font-bold">{title}</p><p className="text-xs text-muted-foreground">{desc}</p></div><Switch checked={on} onCheckedChange={setOn}/></div>}
